head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirst = true; // doCheckReceivers 에서 alert을 한번만 표시하기 위해
scwin.key_acpt_no;
scwin.key_reg_yn;
scwin.key_mkt_nm;
scwin.cmb_ColIndex;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {

};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.key_acpt_no = frame.opener.scwin.key_acpt_no;
    scwin.key_reg_yn = frame.opener.scwin.key_reg_yn;
    scwin.key_mkt_nm = frame.opener.scwin.key_mkt_nm;
    key_isur_cd = frame.opener.key_isur_cd;
};

/**
 * @method
 * @name readInfo
 * @description 선택한 정보 값 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/InquiryDisclosure.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name insert
 * @description 등록 및 수정 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    // 조회공시구분 selectbox 유효성 검증
    const vInqdiscls_tp_cd = cmb_inqdiscls_tp_cd.getValue();
    if (vInqdiscls_tp_cd === ' ') {
        await $c.win.alert("조회공시구분을 선택하세요");
        cmb_inqdiscls_tp_cd.focus();
        return;
    }

    // 조회공시 요구내용 유효성 검증
    const vReq_cont = txa_req_cont.getValue();
    if (vReq_cont === '') {
        await $c.win.alert("조회공시 요구내용을 입력하십시요.");
        txa_req_cont.focus();
        return;
    }

    // 공시시한 날짜 유효성 검증
    const vDeadlineDd = edt_deadline_dd.getValue();
    if (vDeadlineDd.length < 8) {
        await $c.win.alert("공시시한 날짜를 올바르게 입력하십시요.");
        edt_deadline_dd.focus();
        return;
    }

    // 공시시한 시간 유효성 검증
    const vDeadlineHhmm = edt_deadline_hhmm.getValue();
    if (vDeadlineHhmm.length < 4) {
        await $c.win.alert("공시시한 시간을 올바르게 입력하십시요.");
        edt_deadline_hhmm.focus();
        return;
    }

    // binding 되어 있지 않은 값들을 dts_MASTER에 저장
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); // 조회공시요구 접수번호
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_TP_CD", cmb_inqdiscls_tp_cd.getValue()); // 조회공시구분
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_GRND", txa_law.getValue()); // 근거
    dts_MASTER.setCellData(1, "REG_ID", js_id); // 등록자ID
    // alert(dts_MASTER.text);

    let tmpStr = "저장 하시겠습니까?";

    // 수정모드일 때 메세지 변경
    if (scwin.key_reg_yn === 'Y') {
        tmpStr = "수정 하시겠습니까?";
    }
    const vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_inquiry.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_inquiry",
            action : "/InquiryDisclosure.do",
            ref : "dts_MASTER",
            target : "trs_inquiry=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description 조회공시요구서 삭제
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    const rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); // 조회공시요구 접수번호

        let url = "/InquiryDisclosure.do?method=deleteInquiryDsclRequest";
        url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
        url += "&SCREN_ID=" + 'ULDSTF30206.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};

/**
 * @method
 * @name snd
 * @description 수신자 체크 2016-10-10 KBoY
 * @returns {void}
 * @hidden N
 */
scwin.snd = function() {
    // 수신자 체크 2016-10-10 KBoY
    scwin.checkReceivers();
};

/**
 * @method
 * @name doSend
 * @description 조회공시요구서 Email 및 SMS 발송 발송대상 : 공시책임자, 공시담당자
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doSend = async function() {
    if (scwin.checkFileSize() === false) {
        await $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    let first_result = false;
    scwin.isFirst = false;
    // 첨부파일 창이 열려있지 않을 경우에 질문
    if (grd_fileList.style.display === "none") {
        first_result = confirm("조회공시요구서 Email발송 시\n첨부파일을 포함하시겠습니까?");
    }
    let second_result;
    if (first_result) {
        // 첨부파일 추가 시 Form화면으로 다시 돌아감
        await $c.win.alert("첨부파일 추가 후 \n'조회공시요구서 발송' 버튼을 다시 클릭하세요");

        // 파일업로드 컴포넌트 show=true 전환
        grd_fileList.show("");
        lbl_tmp_2.show("");
        label_5.show("");
        btn_lineadd.show("");
        btn_linedelete.show("");
        txb_file_name.show("");
    } else {
        if (confirm("공시책임자 및 공시담당자에게 Email과 SMS를 발송합니다.\n(Email 내용은 '미리보기'를 통해 확인 가능)\n계속하시겠습니까?")) {
            second_result = true;
        } else {
            if (!first_result) scwin.isFirst = true;

            else scwin.isFirst = false;
        }
    }
    if (second_result) // [확인] 버튼이 눌려졌을 경우

    {
        let tmp_mkt_id = '1';
        if (scwin.key_mkt_nm === '코스닥') {
            tmp_mkt_id = '2';
        } else if (scwin.key_mkt_nm === '코넥스') {
            tmp_mkt_id = '6';
        }
        dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); // 조회공시요구 접수번호

        let url = "/InquiryDisclosure.do?method=sendInquiryDsclRequest";
        url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
        url += "&MKM_NM=" + tmp_mkt_id;
        url += "&SCREN_ID=" + 'ULDSTF30206.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER, I:pFile=dts_fileData)";
        trs_inquiry.Post();
    }
};

/**
 * @method
 * @name checkReceivers
 * @description SMS 수신인이 없는 경우 에러가 발생하여 미리 체크한다.
 * @returns {void}
 * @hidden N
 */
scwin.checkReceivers = function() {
    const url_list = "/InquiryDisclosure.do?method=checkReceivers&inputMessageId=MAIL_RECEIPTPLACE_OUT" + "&outputMessageId=MAIL_RECEIPTPLACE_OUT";
    const url_cond = "&ISUR_CD=" + key_isur_cd;
    // 그리드의 데이타 조회
    dts_receivers.DataID = encodeURI(url_list + url_cond);
    dts_receivers.reset();
};

/**
 * @method
 * @name doCheckReceivers
 * @description do Check Receivers 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doCheckReceivers = async function() {
    let msg = '';
    let msg2 = '';
    let tmpChrgTpNm = '';
    let tmpPhoneNo = '';
    let tmpEmail = '';
    let isAddedPhoneMsg = false; // 메세지 한번만 추가되도록
    let isAddedEmailMsg = false;
    for (let i = 1; i <= dts_receivers.getRowCount(); i++) {
        tmpChrgTpNm = dts_receivers.getCellData(i, "CHRG_TP_NM");
        tmpPhoneNo = dts_receivers.getCellData(i, "CELLPHONE_NO");
        tmpEmail = dts_receivers.getCellData(i, "EMAIL");
        if (tmpPhoneNo === '') {
            msg += tmpChrgTpNm + '의 등록된 휴대폰 번호가 없습니다.\r\n';
            if (!isAddedPhoneMsg) {
                msg2 += "※ 휴대폰 번호가 없는 대상에게 알림용 'SMS 전송' 불가\r\n";
                isAddedPhoneMsg = true;
            }
        }
        if (tmpEmail === '') {
            msg += tmpChrgTpNm + '의 등록된 메일 주소가 없습니다.\r\n';
            if (!isAddedEmailMsg) {
                msg2 += "※ 메일 주소가 없는 대상에게 '요구서 전송' 불가\r\n";
                isAddedEmailMsg = true;
            }
        }
    }
    if (scwin.isFirst) {
        if (confirm(msg + msg2 + '계속 진행 하시겠습니까?')) {
            await scwin.doSend();
        }
    } else await scwin.doSend();
};

/**
 * @method
 * @name showAlertMsg
 * @description 20210716 else 부분 추가
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showAlertMsg = async function(msg) {
    if (msg.indexOf('50014') !== -1) {
        await $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else if (msg.indexOf('ORA-01400') !== -1) {
        await $c.win.alert('조회공시 요구서 수신 대상자 중 휴대폰 번호가 등록되어 있지 않은 대상자가 존재합니다.\r\n휴대폰 번호 등록 후 진행하시기 바랍니다.');
    } else {
        await $c.win.alert('저장에실패했습니다');
    }
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크
 * @returns {void}
 * @hidden N
 */
scwin.checkFileSize = function() {
    const maxFileSize = 1024 * 30; // 30MB
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dts_fileData.getRowCount(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > maxFileSize) {
        // alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};

/**
 * @method
 * @name dts_receivers_OnLoadCompleted
 * @description dts_receivers 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_receivers_OnLoadCompleted = async function(rowcount) {
    await scwin.doCheckReceivers();
};

/**
 * @method
 * @name img_cls_dd_onclick
 * @description img_cls_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_deadline_dd);
};

/**
 * @method
 * @name trs_inquiry_OnSuccess
 * @description inquiry On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnSuccess = async function() {
    await $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.win.closePopup();
    // 부모창 reload 처리해야함
    $c.frame.path("../").fn_Search();
};

/**
 * @method
 * @name trs_inquiry_OnFail
 * @description inquiry On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnFail = async function() {
    await scwin.showAlertMsg(trs_inquiry.ErrorMsg);
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.insert();
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description 조회공시구분 컬럼값 셋팅
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    // 조회공시구분 컬럼값 셋팅
    scwin.cmb_ColIndex = cmb_inqdiscls_tp_cd.IndexOfColumn("value", txb_req_tp_cd.getValue());
    if (scwin.cmb_ColIndex !== -1) {
        cmb_inqdiscls_tp_cd.setSelectedIndex(scwin.cmb_ColIndex);
    }
};

/**
 * @method
 * @name btn_Snd_onclick
 * @description 「조회공시요구서 발송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Snd_onclick = function() {
    scwin.snd();
};

/**
 * @method
 * @name btn_Preview_onclick
 * @description 「미리보기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Preview_onclick = async function() {
    let tmp_mkt_id = '1';
    if (scwin.key_mkt_nm === '코스닥') {
        tmp_mkt_id = '2';
    } else if (scwin.key_mkt_nm === '코넥스') {
        tmp_mkt_id = '6';
    }
    let url = "/InquiryDisclosure.do?method=previewInquiryDsclRequest";
    url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
    url += "&MKM_NM=" + tmp_mkt_id;
    await $c.frame.CreateDialogFrame("QUSET_PREVIEW", url, "조회공시요구서 미리보기", 200, 0, 610, 770, "window");
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) === 0) {
        fn_filedown(dts_fileData.getCellData(row, "NOTI_SVC_ID"), dts_fileData.getCellData(row, "FILE_SEQ"));
    }
};

scwin.btn_lineadd_onclick = async function() {
    if (dts_fileData.getRowCount() === 5) {
        await $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileData.insertRow();
    inf_find.open();
    const posV = Math.pow(10, 1);
    if (inf_find.getValue() !== "") {
        const fileName = inf_find.getValue();
        if (fileName.indexOf('\') > 0) {,fileName=fileName.substring(fileName.lastIndexOf('\
                ')+1);,dts_fileData.setCellData(dts_fileData.getRowPosition(),"FILE_NAME",inf_find.getValue()),
                ///////////////////////////////////////////////////////
                dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileUrl", inf_find.getValue()), fileSize = inf_find.FileInfo('size'), fileSize = Math.round(fileSize / 1024 * posV) / posV, dts_fileData.setCellData(dts_fileData.getRowPosition(), "FILE_SIZE", fileSize), txb_file_name.setValue(inf_find.getValue()))), {
            dts_fileData: dts_fileData
        },
        function() {
            $c.cp.removeRow(dts_fileData, dts_fileData.getRowPosition());
        },
        function() {
            // 패널라운드 처리
            $c.libRoundPanel.PanelToGroupBox(panel_1);
            scwin.getParentValue();

            // hidden 객체 숨김
            $c.stf.showObj(txb_req_tp_cd, false);
            $c.stf.showObj(grd_fileList, false);
            $c.stf.showObj(lbl_tmp_2, false);
            $c.stf.showObj(label_5, false);
            $c.stf.showObj(btn_lineadd, false);
            $c.stf.showObj(btn_linedelete, false);
            $c.stf.showObj(txb_file_name, false);
            if (scwin.key_reg_yn == 'N') {
                //showObj(btn_Delete, false); // 등록모드라면 삭제버튼 숨김
                $c.stf.showObj(btn_Preview, false); // 등록모드라면 미리보기 버튼 숨김
                $c.stf.showObj(btn_Snd, false); // 등록모드라면 발송 버튼 숨김

            } else {
                btn_Save.src = "../img/btn_modify.gif";
            }

            //근거 항목 고정텍스트 설정
            if (scwin.key_mkt_nm == '유가') {
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호 및 유가증권시장공시규정 제12조";
            } else if (scwin.key_mkt_nm == '코스닥') {
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호 및 코스닥시장공시규정 제10조";
            } else if (scwin.key_mkt_nm == '코넥스') {
                // 근거 내용 변경(20131030)
                //txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코스닥시장공시규정 제50조의5";
                //txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코스닥시장공시규정 제8조";
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코넥스시장공시규정 제8조";
            }

            // 가우스헤더 셋팅
            const sbmOptions = {
                id : "sbm_dts_MASTER",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_MASTER=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

